import secrets

from django.db import migrations, models

# The receipt email's first default text, written for walk-ins only. A
# template still holding it, unedited, gets the wording for every payer.
OLD_BODY = '{{ name }}님, {{ event.name }} 현장 등록 결제가 확인되었습니다.\n\n- 결제 금액: {{ amount }}원\n- 결제일: {{ payment_date }}\n\n[영수증 보기]({{ receipt_link }})\n\n---\n\nDear {{ name }},\n\nYour on-site registration payment for {{ event.name }} has been received.\n\n- Amount paid: KRW {{ amount }}\n- Date: {{ payment_date }}\n\n[View your receipt]({{ receipt_link }})\n\n{{ event.name }}'
NEW_BODY = OLD_BODY.replace('현장 등록 결제', '등록비 결제').replace('on-site registration payment', 'registration payment')


def receipts_for_every_payment(apps, schema_editor):
    PaymentHistory = apps.get_model('main', 'PaymentHistory')
    Event = apps.get_model('main', 'Event')
    # Until now only desk payments had a receipt link; they are the desk ones.
    PaymentHistory.objects.filter(provider='manual', receipt_token__isnull=False).update(is_desk=True)
    for payment in PaymentHistory.objects.filter(receipt_token__isnull=True).only('id'):
        payment.receipt_token = secrets.token_urlsafe(32)
        payment.save(update_fields=['receipt_token'])
    for event in Event.objects.filter(email_template_receipt__body=OLD_BODY).select_related('email_template_receipt'):
        template = event.email_template_receipt
        template.body = NEW_BODY
        template.save(update_fields=['body'])


